rbtree_t *rb_create(rb_value_free_fn value_free)
{
    rbtree_t *t = malloc(sizeof *t);
    if (t == NULL) {
        return NULL;
    }

    t->root = NIL;
    t->size = 0;
    t->value_free = value_free;

    return t;
}

int rb_insert(rbtree_t *t, const char *key, void *value)
{
    struct rb_node *parent = NIL;
    struct rb_node *existing = bst_search(t, key, &parent);

    if (existing != NIL) {
        if (t->value_free != NULL) {
            t->value_free(existing->value);
        }
        existing->value = value;
        return 0;
    }

    struct rb_node *z = node_alloc();
    if (z == NULL) {
        return -1;
    }

    z->key = copy_key(key);
    if (z->key == NULL) {
        goto cleanup_node;
    }
    z->value = value;
    z->parent = parent;

    if (parent == NIL) {
        t->root = z;
    } else if (strcmp(key, parent->key) < 0) {
        parent->left = z;
    } else {
        parent->right = z;
    }

    t->size++;
    /* TODO: insert_fixup(t, z) once rotations/fixup land -- until then
     * this is a plain (unbalanced) BST insert. */
    return 0;

cleanup_node:
    free(z);
    return -1;
}

