static void rotate_left(rbtree_t *t, struct rb_node *x)
{
    struct rb_node *y = x->right;
    x->right = y->left;

    if (y->left != NIL) {
        y->left->parent = x;
    }

    y->parent = x->parent;

    if (x->parent==NIL) {
        t->root = y;
    }

    else if (x == x->parent->left) {
        x->parent->left = y;
    }
    else {x->parent->right = y;
    }

    y->left=x;
    x->parent = y;
}

static void rotate_right(rbtree_t *t, struct rb_node *x) {

}



